export function SectionElement({
  heading = "{{heading}}",
  body = "{{body}}",
  accent = "{{accent}}",
  divider = {{divider}},
}) {
  const style = { padding: "16px 14px", borderBottom: divider ? `1.5px dashed ${accent}` : "none" };
  return (
    <div style={{ width: 360, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 8, borderRadius: 12 }}>
      <section style={style}>
        <p style={{ margin: "0 0 6px", font: "700 10px ui-monospace, monospace", color: accent, textTransform: "uppercase" }}>&lt;section&gt;</p>
        <h2 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 700 }}>{heading}</h2>
        <p style={{ margin: 0, color: "#241430aa", fontSize: 13 }}>{body}</p>
      </section>
      <section style={{ padding: "16px 14px" }}>
        <p style={{ margin: "0 0 6px", font: "700 10px ui-monospace, monospace", color: accent, textTransform: "uppercase" }}>&lt;section&gt;</p>
        <h2 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 700 }}>Another theme</h2>
        <p style={{ margin: 0, color: "#241430aa", fontSize: 13 }}>Each section is its own self-contained thematic block, stacking in document order.</p>
      </section>
    </div>
  );
}
